const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var arizona = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'Arizona'));

  var date2017 = ['2017-07-15', '2017-07-22'];
  var baselineYears = ee.List.sequence(2001, 2010);

  // 2. Data Acquisition
  function getLSTCollection(startDate, endDate) {
    return ee.ImageCollection('MODIS/061/MYD11A2')
      .filterBounds(arizona)
      .filterDate(startDate, endDate)
      .select('LST_Day_1km');
  }

  var coll2017 = getLSTCollection(date2017[0], date2017[1]);
  var coll2017Size = coll2017.size().getInfo();

  // Handle empty collection for 2017
  if (coll2017Size === 0) {
    print("2017 Images: 0");
    print("<answer>C1</answer>");
    return;
  }

  // 3. Baseline Collection Processing
  var baselineColl = ee.ImageCollection.fromImages(
    baselineYears.map(function(year) {
      var start = ee.Date.fromYMD(year, 7, 15);
      var end = ee.Date.fromYMD(year, 7, 22);
      var yearlyColl = getLSTCollection(start, end);
      var meanImg = yearlyColl.mean().multiply(0.02).subtract(273.15);
      return meanImg.set('year', year);
    })
  ).filter(ee.Filter.notNull(['LST_Day_1km']));

  var baselineSize = baselineColl.size().getInfo();

  // Check baseline data
  if (baselineSize === 0) {
    print("Baseline Images: 0");
    print("<answer>C1</answer>");
    return;
  }

  // 4. Calculate means
  var mean2017 = coll2017.mean()
    .multiply(0.02).subtract(273.15); // Convert to Celsius

  var baselineMean = baselineColl.mean();

  // 5. Pixel count validation
  var stats2017 = mean2017.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: arizona,
    scale: 1000,
    maxPixels: 1e9
  });

  var statsBaseline = baselineMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: arizona,
    scale: 1000,
    maxPixels: 1e9
  });

  var count2017 = stats2017.get('LST_Day_1km').getInfo();
  var countBaseline = statsBaseline.get('LST_Day_1km').getInfo();

  if (count2017 === 0 || countBaseline === 0) {
    print("2017 Pixels: " + count2017);
    print("Baseline Pixels: " + countBaseline);
    print("<answer>C2</answer>");
    return;
  }

  // 6. Calculate temperature values
  var temp2017 = mean2017.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: arizona,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  var tempBaseline = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: arizona,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  // 7. Validation & Final Answer
  print("2017 Images: " + coll2017Size + " (Temp: " + temp2017.toFixed(2) + "°C)");
  print("Baseline Years: " + baselineSize + " (Temp: " + tempBaseline.toFixed(2) + "°C)");
  print("2017 Pixels: " + count2017 + ", Baseline Pixels: " + countBaseline);

  if (temp2017 === null || tempBaseline === null || 
      Math.abs(temp2017) > 100 || Math.abs(tempBaseline) > 100) {
    print("<answer>C3</answer>");
  } else if (temp2017 > tempBaseline) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
